window.RP_SESSION={"id":"S-86cad0f2de90","messages":[{"id":"RP-II-0103681","time":"2026-05-24T02:53:00+09:00","room":"RP II","name":"카프리제","profile":"카프리제 씨","identity":"reviewed","type":"dialogue","body":"“ 에고… 허리야… ”\n\n식자재 잔뜩 쌓아둔 창고 안을 열심히 둘러보며 상한 재료가 혹시 있는지 확인하느라 바빴던 카프리제 씨. 무거운걸 계속 들었다가 놨다 해서인지 허리가 아픈 모양.\n\n아무튼 그렇게 버릴 오래된 식재료들을 한데 모아놨습니다.\n\n“ 생각보다 많네… 하아, 이것도 다 낭비인데. ”","characters":["P-5e15eed74117"]}]};
